1	'use client';
2	
3	import { Text, Tooltip } from '@mantine/core';
4	import type { TableName } from 'prisma/zod/schemas';
5	import { TableNameSchema } from 'prisma/zod/schemas';
6	import type { PlayerRecordType } from 'prisma/zod/schemas/models/PlayerRecord.schema';
7	
8	export interface Props {
9	    table: TableName;
10	    playerRecord: PlayerRecordType;
11	}
12	
